class Base {
public:
    virtual void action() const { /* Base Implementation */ }
    virtual ~Base() = default; // Required for proper Derived cleanup
};

class Derived : public Base {
    int specific_data = 10;
public:
    void action() const override { /* Derived logic uses specific_data */ }
};

// Slicing Example: Only Base part copied (specific_data lost)
// Base sliced = Derived();

// Polymorphism (Pointers/References) avoids slicing:
Derived d_obj;
Base* ptr = &d_obj;
ptr->action(); // Runtime dispatch calls Derived::action()

Base& ref = d_obj;
ref.action(); // Runtime dispatch
